// Base query: CostsThisMonth
// Returns all cost records for the current month
Costs()
| where ChargePeriodStart >= startofmonth(now())

// Base query: CostsLastMonth
// Returns all cost records for the previous calendar month
Costs()
| where ChargePeriodStart >= startofmonth(now(), -1)
| where ChargePeriodStart < startofmonth(now())

// Base query: CostsByMonth
// Returns all cost records for the last 13 months (used by 44 tile queries)
// Tiles aggregate this data by month, subscription, service, region, etc.
Costs()
| where ChargePeriodStart >= startofmonth(now(), -13)

// Base query: CostsByDay
// Returns all cost records for the last 2 months (daily analysis)
// Tiles aggregate by day for resource counts, SKU analysis, etc.
Costs()
| where ChargePeriodStart >= startofmonth(now(), -2)

// Base query: CostsByDayAHB
// Returns cost records enriched with Azure Hybrid Benefit (AHB) columns
// Used by 4 tile queries analyzing license utilization
Costs()
| where ChargePeriodStart >= startofmonth(now(), -2)
| extend x_SkuCoreCount = toint(column_ifexists('x_SkuCoreCount', 0))
| extend x_SkuLicenseUnusedQuantity = case(
    column_ifexists('x_SkuLicenseStatus', '') == 'Enabled' and column_ifexists('x_SkuLicenseQuantity', 0) > 0,
    column_ifexists('x_SkuLicenseQuantity', 0) - toint(ConsumedQuantity),
    0)

